alter table academy_private.google_session_proofs enable row level security;
revoke all on academy_private.google_proof_challenges, academy_private.google_session_proofs from public,anon,authenticated,service_role;

-- p_user/p_session/state/nonce must be created and checked by the trusted
-- service, not by untrusted browser data. Start only for a verified OAuth
-- session; the service must reject password and ambiguous methods itself.
create function public.review_google_proof_begin(p_user uuid,p_session uuid,p_state_hash text,p_cookie_hash text,p_nonce text,p_verifier text)
returns void language plpgsql security definer set search_path = '' as $$
begin
  if not academy_private.signup_release_enabled('proof') then raise exception 'Unavailable'; end if;
  if not exists(select 1 from auth.sessions s where s.id=p_session and s.user_id=p_user and (s.not_after is null or s.not_after>clock_timestamp())) then
    raise exception 'Proof unavailable';
  end if;
  -- Bound consecutive unfinished starts per session to five in five minutes.
  -- A restart invalidates the old state and resets its callback-read allowance.
  -- A successful finish deletes the row and resets this counter, so this is NOT
  -- a replacement for ingress/IP/account distributed rate limiting.
  insert into academy_private.google_proof_challenges(state_hash,cookie_hash,nonce,code_verifier,user_id,session_id,expires_at)
  values(p_state_hash,p_cookie_hash,p_nonce,p_verifier,p_user,p_session,clock_timestamp()+interval '5 minutes')
  on conflict(session_id) do update set state_hash=excluded.state_hash,cookie_hash=excluded.cookie_hash,nonce=excluded.nonce,code_verifier=excluded.code_verifier,user_id=excluded.user_id,expires_at=excluded.expires_at,
    start_count=case when academy_private.google_proof_challenges.start_window_at<=clock_timestamp()-interval '5 minutes' then 1 else academy_private.google_proof_challenges.start_count+1 end,
    start_window_at=case when academy_private.google_proof_challenges.start_window_at<=clock_timestamp()-interval '5 minutes' then clock_timestamp() else academy_private.google_proof_challenges.start_window_at end,
    read_count=0
  where academy_private.google_proof_challenges.start_window_at<=clock_timestamp()-interval '5 minutes' or academy_private.google_proof_challenges.start_count<5;
  if not found then raise exception 'Proof unavailable'; end if;
end; $$;
revoke all on function public.review_google_proof_begin(uuid,uuid,text,text,text,text) from public,anon,authenticated;
grant execute on function public.review_google_proof_begin(uuid,uuid,text,text,text,text) to service_role;

-- Only the backend may retrieve the verifier and stored nonce, after hashing
-- the state and the independent HttpOnly browser cookie. The nonce is also sent
-- to Google; the code verifier must remain server-side.
create function public.review_google_proof_read(p_state_hash text,p_cookie_hash text)
returns table(nonce text,code_verifier text) language sql volatile security definer set search_path = '' as $$
  update academy_private.google_proof_challenges c set read_count=c.read_count+1
  from auth.sessions s
  where academy_private.signup_release_enabled('proof') and s.id=c.session_id and s.user_id=c.user_id
    and c.state_hash=p_state_hash and c.cookie_hash=p_cookie_hash and c.expires_at>statement_timestamp()
    and c.read_count<5 and (s.not_after is null or s.not_after>statement_timestamp())
  returning c.nonce,c.code_verifier;
$$;
revoke all on function public.review_google_proof_read(text,text) from public,anon,authenticated;
grant execute on function public.review_google_proof_read(text,text) to service_role;

-- nonce and subject must come exclusively from an already VERIFIED Google
-- ID token. The state hash must be checked against the browser's CSRF cookie.
-- Atomic delete makes a successful challenge one-use, including under races.
create function public.review_google_proof_finish(p_state_hash text,p_cookie_hash text,p_nonce text,p_subject text)
returns void language plpgsql security definer set search_path = '' as $$
declare c academy_private.google_proof_challenges%rowtype; session_end timestamptz;
begin
  if not academy_private.signup_release_enabled('proof') then raise exception 'Unavailable'; end if;
  delete from academy_private.google_proof_challenges where state_hash=p_state_hash and cookie_hash=p_cookie_hash and nonce=p_nonce and expires_at>clock_timestamp() returning * into c;
  if not found then raise exception 'Proof unavailable'; end if;
  select s.not_after into session_end from auth.sessions s where s.id=c.session_id and s.user_id=c.user_id and (s.not_after is null or s.not_after>clock_timestamp()) for key share;
  if not found or not exists(select 1 from auth.identities i where i.user_id=c.user_id and i.provider='google' and i.provider_id=p_subject) then
    raise exception 'Proof unavailable';
  end if;
  insert into academy_private.google_session_proofs(session_id,user_id,google_subject,expires_at)
  values(c.session_id,c.user_id,p_subject,least(clock_timestamp()+interval '1 hour', coalesce(session_end,'infinity'::timestamptz)))
  on conflict(session_id) do update set user_id=excluded.user_id,google_subject=excluded.google_subject,expires_at=excluded.expires_at;
end; $$;
revoke all on function public.review_google_proof_finish(text,text,text,text) from public,anon,authenticated;
grant execute on function public.review_google_proof_finish(text,text,text,text) to service_role;

-- This predicate alone is not role authorization. It checks the verified
-- session's OAuth AMR, live session, matching current Google identity and proof.
create function academy_private.review_google_proof_current()
returns boolean language sql stable security definer set search_path = '' as $$
  select academy_private.signup_release_enabled('proof') and academy_private.role_session_method_allows('parent') and exists (
    select 1 from academy_private.google_session_proofs p
      join auth.sessions s on s.id=p.session_id and s.user_id=p.user_id
      join auth.identities i on i.user_id=p.user_id and i.provider='google' and i.provider_id=p.google_subject
    where p.user_id=(select auth.uid()) and p.session_id::text=(select auth.jwt()->>'session_id')
      and p.expires_at>statement_timestamp() and (s.not_after is null or s.not_after>statement_timestamp())
  );
$$;
revoke all on function academy_private.review_google_proof_current() from public,anon;
grant execute on function academy_private.review_google_proof_current() to authenticated;

-- Identity-only status feedback; it does not grant a role or family access.
create function public.review_google_proof_status() returns boolean
language sql stable security definer set search_path = '' as $$
  select academy_private.review_google_proof_current();
$$;
revoke all on function public.review_google_proof_status() from public,anon,service_role;
grant execute on function public.review_google_proof_status() to authenticated;

create table academy_private.google_proof_ingress_limits (
  scope text not null check(scope in ('network','account')),
  key_hash text not null check(key_hash ~ '^[a-f0-9]{64}$'),
  window_started_at timestamptz not null,
  attempts integer not null check(attempts between 1 and 120),
  primary key(scope,key_hash)
);
create index google_proof_ingress_limits_expiry on academy_private.google_proof_ingress_limits(window_started_at);
alter table academy_private.google_proof_ingress_limits enable row level security;
revoke all on academy_private.google_proof_ingress_limits from public,anon,authenticated,service_role;

create function public.review_google_proof_rate_limit(p_scope text,p_key_hash text)
returns boolean language plpgsql security definer set search_path='' as $$
declare allowed boolean; instant timestamptz:=clock_timestamp(); max_attempts integer;
begin
  if not academy_private.signup_release_enabled('proof') then raise exception 'Unavailable'; end if;
  if p_scope is null or p_scope not in ('network','account') or p_key_hash is null or p_key_hash !~ '^[a-f0-9]{64}$' then raise exception 'Unavailable'; end if;
  max_attempts:=case when p_scope='network' then 120 else 20 end;
  -- Incremental bounded cleanup; old keyed hashes are not retained indefinitely
  -- when the endpoint is in use. A separate scheduled cleanup is still needed
  -- for periods with no traffic or when the endpoint is disabled.
  delete from academy_private.google_proof_ingress_limits where (scope,key_hash) in (
    select x.scope,x.key_hash from academy_private.google_proof_ingress_limits x
    where x.window_started_at<instant-interval '1 day' order by x.window_started_at,x.scope,x.key_hash limit 25
  );
  insert into academy_private.google_proof_ingress_limits(scope,key_hash,window_started_at,attempts)
    values(p_scope,p_key_hash,instant,1)
  on conflict(scope,key_hash) do update set
    window_started_at=case when academy_private.google_proof_ingress_limits.window_started_at<=instant-interval '10 minutes' then instant else academy_private.google_proof_ingress_limits.window_started_at end,
    attempts=case when academy_private.google_proof_ingress_limits.window_started_at<=instant-interval '10 minutes' then 1 else academy_private.google_proof_ingress_limits.attempts+1 end
  where academy_private.google_proof_ingress_limits.window_started_at<=instant-interval '10 minutes'
     or academy_private.google_proof_ingress_limits.attempts<max_attempts
  returning true into allowed;
  return coalesce(allowed,false);
end; $$;
revoke all on function public.review_google_proof_rate_limit(text,text) from public,anon,authenticated,service_role;
grant execute on function public.review_google_proof_rate_limit(text,text) to service_role;

create function public.review_student_self_enroll(p_expected_user uuid, p_display_name text, p_grade smallint)
returns text language plpgsql security definer set search_path = '' as $$
declare
  actor uuid := (select auth.uid());
  display_name text := pg_catalog.btrim(p_display_name);
  already_student boolean;
begin
  if not academy_private.signup_release_enabled('enrollment') then raise exception 'Unavailable'; end if;
  if actor is null or p_expected_user is distinct from actor or academy_private.review_google_proof_current() is distinct from true
     or p_grade is null or p_grade not between 1 and 7
     or display_name is null or pg_catalog.char_length(display_name) not between 1 and 100
     or display_name ~ '[[:cntrl:]]' then
    raise exception 'Enrollment unavailable';
  end if;
  -- Avoid granting privileges to an unconfirmed, anonymous, deleted or banned
  -- account, including accounts whose existing JWT has not yet expired.
  perform 1 from auth.users u where u.id=actor and u.email_confirmed_at is not null
    and u.deleted_at is null and not coalesce(u.is_anonymous,false)
    and (u.banned_until is null or u.banned_until<=statement_timestamp()) for key share;
  if not found then raise exception 'Enrollment unavailable'; end if;

  -- Serialize with lifecycle grants/revocations. Never restore a revoked role.
  perform academy_private.lock_role_lifecycle(actor,'student');
  select exists(select 1 from public.user_roles where user_id=actor and role='student') into already_student;
  if already_student then
    if not exists(select 1 from public.profiles where id=actor)
       or not exists(select 1 from public.student_grades where student_id=actor) then
      raise exception 'Enrollment unavailable';
    end if;
    return 'already_enrolled';
  end if;
  if exists(select 1 from academy_private.role_lifecycle_epochs where user_id=actor and role='student')
     or exists(select 1 from public.student_grades where student_id=actor) then
    raise exception 'Enrollment unavailable';
  end if;
  -- Existing profiles may belong to another role: preserve their name exactly.
  insert into public.profiles(id,display_name,first_name) values(actor,display_name,display_name)
    on conflict(id) do nothing;
  insert into public.user_roles(user_id,role) values(actor,'student');
  insert into public.student_grades(student_id,grade) values(actor,p_grade);
  return 'created';
end; $$;
revoke all on function public.review_student_self_enroll(uuid,text,smallint) from public,anon,authenticated,service_role;
grant execute on function public.review_student_self_enroll(uuid,text,smallint) to authenticated;

create function public.review_parent_self_enroll(p_expected_user uuid,p_display_name text)
returns text language plpgsql security definer set search_path='' as $$
declare actor uuid := (select auth.uid()); display_name text := pg_catalog.btrim(p_display_name);
begin
  if not academy_private.signup_release_enabled('enrollment') then raise exception 'Unavailable'; end if;
  if actor is null or actor is distinct from p_expected_user
     or academy_private.review_google_proof_current() is distinct from true
     or display_name is null or pg_catalog.char_length(display_name) not between 1 and 100
     or display_name ~ '[[:cntrl:]]' then raise exception 'Enrollment unavailable'; end if;
  perform 1 from auth.users u where u.id=actor and u.email_confirmed_at is not null
    and u.deleted_at is null and not coalesce(u.is_anonymous,false)
    and (u.banned_until is null or u.banned_until<=statement_timestamp()) for key share;
  if not found then raise exception 'Enrollment unavailable'; end if;
  perform academy_private.lock_role_lifecycle(actor,'parent');
  if exists(select 1 from public.user_roles where user_id=actor and role='parent') then
    if not exists(select 1 from public.profiles where id=actor) then raise exception 'Enrollment unavailable'; end if;
    return 'already_enrolled';
  end if;
  -- Never use self-service to reinstate a revoked role.
  if exists(select 1 from academy_private.role_lifecycle_epochs where user_id=actor and role='parent') then
    raise exception 'Enrollment unavailable';
  end if;
  insert into public.profiles(id,display_name,first_name) values(actor,display_name,display_name) on conflict(id) do nothing;
  insert into public.user_roles(user_id,role) values(actor,'parent');
  return 'created';
end; $$;
revoke all on function public.review_parent_self_enroll(uuid,text) from public,anon,authenticated,service_role;
grant execute on function public.review_parent_self_enroll(uuid,text) to authenticated;

create table academy_private.parent_link_applications (
  id uuid primary key,
  parent_id uuid not null references public.profiles(id) on delete cascade,
  student_id uuid not null,
  state text not null default 'pending' check (state in ('pending','approved','rejected','cancelled')),
  created_at timestamptz not null default clock_timestamp(),
  resolved_at timestamptz,
  resolved_by uuid references public.profiles(id) on delete restrict,
  authorization_reference text,
  check (parent_id<>student_id),
  check ((state='pending' and resolved_at is null and resolved_by is null and authorization_reference is null)
    or (state='cancelled' and resolved_at is not null and resolved_by is null and authorization_reference is null)
    or (state in ('approved','rejected') and resolved_at is not null and resolved_by is not null and authorization_reference is not null))
);
create index parent_link_applications_parent_recent on academy_private.parent_link_applications(parent_id,created_at);
create unique index parent_link_applications_one_pending on academy_private.parent_link_applications(parent_id,student_id) where state='pending';
alter table academy_private.parent_link_applications enable row level security;
revoke all on academy_private.parent_link_applications from public,anon,authenticated,service_role;

-- No existence lookup or child information is disclosed to the parent.
create function public.review_parent_link_request(p_request uuid,p_expected_parent uuid,p_student uuid)
returns text language plpgsql security definer set search_path='' as $$
declare actor uuid:=(select auth.uid()); existing academy_private.parent_link_applications%rowtype;
begin
  if not academy_private.signup_release_enabled('parent_link') then raise exception 'Unavailable'; end if;
  if actor is null or actor is distinct from p_expected_parent or p_request is null or p_student is null
     or actor=p_student or not academy_private.has_role('parent')
     or academy_private.review_google_proof_current() is distinct from true then raise exception 'Request unavailable'; end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('academy.parent-application:' || actor::text,0));
  -- Recheck a role lock after waiting so revocation cannot race submission.
  perform 1 from public.user_roles r where r.user_id=actor and r.role='parent' for key share;
  if not found or not academy_private.has_role('parent') or academy_private.review_google_proof_current() is distinct from true then raise exception 'Request unavailable'; end if;
  select * into existing from academy_private.parent_link_applications where id=p_request;
  if found then
    if existing.parent_id<>actor or existing.student_id<>p_student then raise exception 'Request unavailable'; end if;
    return 'received';
  end if;
  if (select count(*) from academy_private.parent_link_applications where parent_id=actor and state='pending')>=5
     or (select count(*) from academy_private.parent_link_applications where parent_id=actor and created_at>clock_timestamp()-interval '1 day')>=20
     or exists(select 1 from academy_private.parent_link_applications where parent_id=actor and student_id=p_student and state='pending') then
    raise exception 'Request unavailable';
  end if;
  insert into academy_private.parent_link_applications(id,parent_id,student_id) values(p_request,actor,p_student);
  return 'received';
end; $$;

create function public.review_parent_link_my_requests()
returns table(id uuid,student_id uuid,state text,created_at timestamptz)
language plpgsql stable security definer set search_path='' as $$
begin
  if not academy_private.signup_release_enabled('parent_link') then raise exception 'Unavailable'; end if;
  if not academy_private.has_role('parent') or academy_private.review_google_proof_current() is distinct from true then raise exception 'Request unavailable'; end if;
  return query select a.id,a.student_id,a.state,a.created_at from academy_private.parent_link_applications a
    where a.parent_id=(select auth.uid()) and a.created_at>statement_timestamp()-interval '90 days'
    order by a.created_at desc,a.id limit 20;
end; $$;

create function public.review_parent_link_cancel(p_expected_parent uuid,p_request uuid)
returns boolean language plpgsql security definer set search_path='' as $$
declare actor uuid := (select auth.uid());
begin
  if not academy_private.signup_release_enabled('parent_link') then raise exception 'Unavailable'; end if;
  if actor is null or actor is distinct from p_expected_parent or not academy_private.has_role('parent') or academy_private.review_google_proof_current() is distinct from true then raise exception 'Request unavailable'; end if;
  perform 1 from public.user_roles where user_id=actor and role='parent' for key share;
  if not found or not academy_private.has_role('parent') or academy_private.review_google_proof_current() is distinct from true then raise exception 'Request unavailable'; end if;
  update academy_private.parent_link_applications set state='cancelled',resolved_at=clock_timestamp()
    where id=p_request and parent_id=actor and state='pending';
  return found;
end; $$;

create function public.review_admin_parent_link_applications()
returns table(id uuid,parent_id uuid,student_id uuid,created_at timestamptz)
language plpgsql stable security definer set search_path='' as $$
begin
  if not academy_private.signup_release_enabled('parent_link') then raise exception 'Unavailable'; end if;
  if not academy_private.has_role('admin') then raise exception 'Request unavailable'; end if;
  return query select a.id,a.parent_id,a.student_id,a.created_at from academy_private.parent_link_applications a
    where a.state='pending' order by a.created_at,a.id limit 100;
end; $$;

-- The administrator must independently establish identity and authority.
-- The reference is an internal record locator, not proof of authority itself.
create function public.review_admin_parent_link_decide(p_expected_admin uuid,p_request uuid,p_decision text,p_reference text)
returns text language plpgsql security definer set search_path='' as $$
declare actor uuid:=(select auth.uid()); item academy_private.parent_link_applications%rowtype; outcome text;
begin
  if not academy_private.signup_release_enabled('parent_link') then raise exception 'Unavailable'; end if;
  if actor is null or actor is distinct from p_expected_admin or p_request is null or p_decision is null or p_decision not in ('approve','reject')
     or p_reference is null or p_reference !~ '^[A-Za-z0-9][A-Za-z0-9._-]{0,79}$'
     or not academy_private.has_role('admin') then raise exception 'Request unavailable'; end if;
  perform 1 from public.user_roles where user_id=actor and role='admin' for key share;
  if not found then raise exception 'Request unavailable'; end if;
  select * into item from academy_private.parent_link_applications where id=p_request for update;
  if not found or actor=item.parent_id or actor=item.student_id then raise exception 'Request unavailable'; end if;
  outcome:=case when p_decision='approve' then 'approved' else 'rejected' end;
  if item.state=outcome and item.resolved_by=actor and item.authorization_reference=p_reference then return outcome; end if;
  if item.state<>'pending' then raise exception 'Request unavailable'; end if;
  if p_decision='approve' then
    perform public.admin_establish_parent_link(item.parent_id,item.student_id,p_reference);
  end if;
  update academy_private.parent_link_applications set state=outcome,resolved_at=clock_timestamp(),resolved_by=actor,authorization_reference=p_reference where id=p_request;
  return outcome;
end; $$;
revoke all on function public.review_parent_link_request(uuid,uuid,uuid), public.review_parent_link_my_requests(), public.review_parent_link_cancel(uuid,uuid), public.review_admin_parent_link_applications(), public.review_admin_parent_link_decide(uuid,uuid,text,text) from public,anon,authenticated,service_role;
grant execute on function public.review_parent_link_request(uuid,uuid,uuid), public.review_parent_link_my_requests(), public.review_parent_link_cancel(uuid,uuid), public.review_admin_parent_link_applications(), public.review_admin_parent_link_decide(uuid,uuid,text,text) to authenticated;


-- Invoked by a trusted operator/scheduler, not browser/service-role clients.
-- Batch limits avoid unbounded locks and don't delete enrollment or link records.
create index google_proof_challenges_expiry on academy_private.google_proof_challenges(expires_at);
create index google_session_proofs_expiry on academy_private.google_session_proofs(expires_at);
create function academy_private.signup_cleanup_expired(p_limit integer default 500)
returns table(challenges bigint,proofs bigint,rate_limits bigint)
language plpgsql security definer set search_path='' as $$
begin
  if p_limit is null or p_limit < 1 or p_limit > 5000 then raise exception 'Invalid batch'; end if;
  with picked as (select state_hash from academy_private.google_proof_challenges where expires_at<statement_timestamp() order by expires_at,state_hash limit p_limit for update skip locked),
    deleted as (delete from academy_private.google_proof_challenges c using picked p where c.state_hash=p.state_hash returning 1)
    select count(*) into challenges from deleted;
  with picked as (select session_id from academy_private.google_session_proofs where expires_at<statement_timestamp() order by expires_at,session_id limit p_limit for update skip locked),
    deleted as (delete from academy_private.google_session_proofs c using picked p where c.session_id=p.session_id returning 1)
    select count(*) into proofs from deleted;
  with picked as (select scope,key_hash from academy_private.google_proof_ingress_limits where window_started_at<statement_timestamp()-interval '1 day' order by window_started_at,scope,key_hash limit p_limit for update skip locked),
    deleted as (delete from academy_private.google_proof_ingress_limits c using picked p where c.scope=p.scope and c.key_hash=p.key_hash returning 1)
    select count(*) into rate_limits from deleted;
  return next;
end; $$;
revoke all on function academy_private.signup_cleanup_expired(integer) from public,anon,authenticated,service_role;
commit;
